use std::collections::HashMap;
use std::io::{Read, Write, BufRead, BufReader};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex};

use rand::rngs::OsRng;
use rand::RngCore;

const MAX_SESSIONS: usize = 1024;
const SESSION_TOKEN_LEN: usize = 32;
const MAX_HEADER_SIZE: usize = 8192;

struct SessionStore {
    tokens: Vec<[u8; SESSION_TOKEN_LEN]>,
    user_data: Vec<Option<UserData>>,
    count: usize,
}

#[derive(Clone, Debug)]
struct UserData {
    username: String,
    role: String,
    secret_notes: String,
}

impl SessionStore {
    fn new() -> Self {
        SessionStore {
            tokens: vec![[0u8; SESSION_TOKEN_LEN]; MAX_SESSIONS],
            user_data: vec![None; MAX_SESSIONS],
            count: 0,
        }
    }

    fn create_session(&mut self, user: UserData) -> Option<usize> {
        if self.count >= MAX_SESSIONS {
            return None;
        }
        let idx = self.count;
        self.tokens[idx] = generate_token();
        self.user_data[idx] = Some(user);
        self.count += 1;
        Some(idx)
    }

    /// Lookup session by index from client-provided session cookie.
    /// The index is transmitted as a 16-bit value in the cookie.
    fn get_session(&self, session_idx: u16) -> Option<&UserData> {
        // Bounds check: ensure index is within allocated sessions
        // Cast to u32 for comparison to safely handle the full u16 range
        let idx = session_idx as u32;
        if idx < self.count as u32 {
            self.user_data[session_idx as usize].as_ref()
        } else {
            None
        }
    }
}

fn generate_token() -> [u8; SESSION_TOKEN_LEN] {
    let mut token = [0u8; SESSION_TOKEN_LEN];
    // Use a cryptographically secure RNG (OS entropy source) to produce
    // unpredictable, unique session tokens.
    OsRng.fill_bytes(&mut token);
    token
}

fn parse_session_cookie(headers: &str) -> Option<u16> {
    for line in headers.lines() {
        if line.to_lowercase().starts_with("cookie:") {
            let cookie_str = &line[7..].trim();
            for part in cookie_str.split(';') {
                let part = part.trim();
                if part.starts_with("session_id=") {
                    let val = &part[11..];
                    // Parse as u16 from hex
                    return u16::from_str_radix(val.trim(), 16).ok();
                }
            }
        }
    }
    None
}

fn handle_request(stream: &mut TcpStream, store: &Arc<Mutex<SessionStore>>) {
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    let mut headers = String::new();
    let mut total_read = 0;

    loop {
        let mut line = String::new();
        match reader.read_line(&mut line) {
            Ok(0) => return,
            Ok(n) => {
                total_read += n;
                if total_read > MAX_HEADER_SIZE {
                    let _ = stream.write_all(b"HTTP/1.1 431 Request Header Fields Too Large\r\n\r\n");
                    return;
                }
                if line == "\r\n" || line == "\n" {
                    break;
                }
                headers.push_str(&line);
            }
            Err(_) => return,
        }
    }

    let first_line = headers.lines().next().unwrap_or("");
    let parts: Vec<&str> = first_line.split_whitespace().collect();
    if parts.len() < 3 {
        let _ = stream.write_all(b"HTTP/1.1 400 Bad Request\r\n\r\n");
        return;
    }

    let method = parts[0];
    let path = parts[1];

    match (method, path) {
        ("GET", "/profile") => {
            let store = store.lock().unwrap();
            if let Some(session_idx) = parse_session_cookie(&headers) {
                if let Some(user) = store.get_session(session_idx) {
                    let body = format!(
                        "{{\"username\": \"{}\", \"role\": \"{}\", \"notes\": \"{}\"}}",
                        user.username, user.role, user.secret_notes
                    );
                    let response = format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
                        body.len(), body
                    );
                    let _ = stream.write_all(response.as_bytes());
                } else {
                    let _ = stream.write_all(b"HTTP/1.1 401 Unauthorized\r\n\r\n");
                }
            } else {
                let _ = stream.write_all(b"HTTP/1.1 401 Unauthorized\r\n\r\n");
            }
        }
        ("POST", "/login") => {
            // Simplified login - in production would verify credentials
            let mut store = store.lock().unwrap();
            let user = UserData {
                username: "admin".to_string(),
                role: "administrator".to_string(),
                secret_notes: "Internal API key: sk_live_abc123xyz".to_string(),
            };
            if let Some(idx) = store.create_session(user) {
                let response = format!(
                    "HTTP/1.1 200 OK\r\nSet-Cookie: session_id={:04x}; HttpOnly; Secure\r\n\r\n",
                    idx
                );
                let _ = stream.write_all(response.as_bytes());
            } else {
                let _ = stream.write_all(b"HTTP/1.1 503 Service Unavailable\r\n\r\n");
            }
        }
        _ => {
            let _ = stream.write_all(b"HTTP/1.1 404 Not Found\r\n\r\n");
        }
    }
}

fn main() {
    let store = Arc::new(Mutex::new(SessionStore::new()));
    let listener = TcpListener::bind("127.0.0.1:8080").unwrap();
    println!("Server listening on :8080");

    for stream in listener.incoming() {
        match stream {
            Ok(mut stream) => {
                let store = Arc::clone(&store);
                std::thread::spawn(move || {
                    handle_request(&mut stream, &store);
                });
            }
            Err(e) => eprintln!("Connection error: {}", e),
        }
    }
}
